import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringBuilder input = new StringBuilder();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int c;
        while ((c = br.read()) != -1) {
            input.append((char) c);
        }

        String[] inp = input.toString().trim().split("\\s+");
        int n = Integer.parseInt(inp[0]);
        int k = Integer.parseInt(inp[1]);
        String s = inp[2];
        String t = inp[3];

        if (t.charAt(0) == t.charAt(1)) {
            int cntChar = 0;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) == t.charAt(0)) cntChar++;
            }
            long x = Math.min(cntChar + (long) k, (long) n);
            System.out.println(x * (x - 1) / 2);
            return;
        }

        int[][][] f = new int[n + 2][n + 2][n + 2];
        for (int i = 0; i <= n + 1; i++) {
            for (int j = 0; j <= n + 1; j++) {
                Arrays.fill(f[i][j], -100000);
            }
        }
        f[0][0][0] = 0;

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                for (int cnt0 = 0; cnt0 <= i; cnt0++) {
                    if (f[i][j][cnt0] < 0) continue;
                    int e0 = (i < s.length() && s.charAt(i) == t.charAt(0)) ? 1 : 0;
                    int e1 = (i < s.length() && s.charAt(i) == t.charAt(1)) ? 1 : 0;
                    f[i + 1][j][cnt0 + e0] = Math.max(f[i + 1][j][cnt0 + e0], f[i][j][cnt0] + e1 * cnt0);
                    f[i + 1][j + 1][cnt0 + 1] = Math.max(f[i + 1][j + 1][cnt0 + 1], f[i][j][cnt0]);
                    f[i + 1][j + 1][cnt0] = Math.max(f[i + 1][j][cnt0], f[i][j][cnt0] + cnt0);
                }
            }
        }

        int best = Integer.MIN_VALUE;
        for (int i = 0; i <= k; i++) {
            int inner = Integer.MIN_VALUE;
            for (int j = 0; j <= n; j++) {
                inner = Math.max(inner, f[n][i][j]);
            }
            best = Math.max(best, inner);
        }
        System.out.println(best);
    }
}
